53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const FIRST_INSURANCE_RATE = 0.1;
62	const CURSE_SURCHARGE_RATE = 0.5;
63	const HIGH_ENCHANTMENT_THRESHOLD = 5;
64	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
65	const PROCESSING_FEE = 5;
66	const LOYALTY_YEARS_THRESHOLD = 2;
67	const LOYALTY_DISCOUNT_RATE = 0.2;
68	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
69	const ALIKE_BLOCK_SIZE = 3;
70	const ALIKE_BLOCK_PREMIUM = 60;
71	
72	const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
73	  const countsByType = new Map<string, number>();
74	  for (const item of items) {
75	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
76	  }
77	  return countsByType;
78	};
79	
80	const premiumForAlikeGroup = (type: string, count: number): number => {
81	  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
82	  return formsExactlyOneBlock
83	    ? ALIKE_BLOCK_PREMIUM
84	    : count * ITEM_BASE_PREMIUMS[type];
85	};
86	
87	const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
88	  let total = 0;
89	  for (const [type, count] of countItemsByType(items)) {
90	    total += premiumForAlikeGroup(type, count);
91	  }
92	  return total;
93	};
94	
95	const itemSurcharge = (
96	  items: QuoteItem[],
97	  applies: (item: QuoteItem) => boolean,
98	  rate: number,
99	): number =>
100	  items.reduce(
101	    (sum, item) =>
102	      applies(item) ? sum + ITEM_BASE_PREMIUMS[item.type] * rate : sum,
103	    0,
104	  );
105	
106	const calculateCurseSurcharge = (items: QuoteItem[]): number =>
107	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
108	
109	const calculateHighEnchantmentSurcharge = (items: QuoteItem[]): number =>
110	  itemSurcharge(
111	    items,
112	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
113	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
114	  );
115	
116	const calculateQuotePremium = (
117	  items: QuoteItem[],
118	  customer: Customer,
119	  isFollowUpContract: boolean,
120	): number => {
121	  const policyBasePremium = calculatePolicyBasePremium(items);
122	  const curseSurcharge = calculateCurseSurcharge(items);
123	  const highEnchantmentSurcharge = calculateHighEnchantmentSurcharge(items);
124	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
125	  const loyaltyDiscount =
126	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
127	      ? policyBasePremium * LOYALTY_DISCOUNT_RATE
128	      : 0;
129	  const followUpDiscount = isFollowUpContract
130	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
131	    : 0;
132	  return Math.ceil(
133	    policyBasePremium +
134	      curseSurcharge +
135	      highEnchantmentSurcharge +
136	      firstInsuranceSurcharge -
137	      loyaltyDiscount -
138	      followUpDiscount +
139	      PROCESSING_FEE,
140	  );
141	};
