143	const ITEM_INSURANCE_VALUES: Record<string, number> = {
144	  sword: 1000,
145	  amulet: 600,
146	  rune: 250,
147	};
148	const DEDUCTIBLE = 100;
149	const PAYOUT_CAP_MULTIPLIER = 2;
150	// Claim-side threshold — a separate business rule from the premium-side
151	// HIGH_ENCHANTMENT_THRESHOLD (5); do not merge them.
152	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
153	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
154	
155	const calculateInsuranceSum = (items: QuoteItem[]): number =>
156	  items.reduce((sum, item) => sum + ITEM_INSURANCE_VALUES[item.type], 0);
157	
158	const processClaim = (claimStep: ClaimStep, policy: QuoteStep): ClaimResult => {
159	  const payoutCap = calculateInsuranceSum(policy.items) * PAYOUT_CAP_MULTIPLIER;
160	  const totalReimbursed = claimStep.incident.damages.reduce((sum, damage) => {
161	    const damagedItem = policy.items.find(
162	      (item) => item.type === damage.itemType,
163	    );
164	    const reimbursed =
165	      (damagedItem?.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD
166	        ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
167	        : damage.amount;
168	    return sum + (reimbursed - DEDUCTIBLE);
169	  }, 0);
170	  const payout = Math.floor(totalReimbursed);
171	  return { payout, remainingCap: payoutCap - payout };
172	};
173	
174	export const runScenario = (scenario: Scenario): ScenarioResult => {
175	  const results = scenario.steps.map((step, index): StepResult => {
176	    if (step.op === "claim") {
177	      const policy = scenario.steps[step.policy] as QuoteStep;
178	      return processClaim(step, policy);
179	    }
180	    const isFollowUpContract = index > 0;
181	    return {
182	      premium: calculateQuotePremium(
183	        step.items,
184	        scenario.customer,
185	        isFollowUpContract,
186	      ),
187	    };
188	  });
189	  return { results };
190	};
