const reimbursementForDamage = (
  damage: Damage,
  insuredItems: QuoteItem[],
): number => {
  const damagedItem = insuredItems.find(
    (item) => item.type === damage.itemType,
  );
  const hasHighEnchantment =
    (damagedItem?.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD;
  const reimbursedAmount = hasHighEnchantment
    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : damage.amount;
  return reimbursedAmount - DEDUCTIBLE;
};

const processClaim = (claimStep: ClaimStep, policy: QuoteStep): ClaimResult => {
  const payoutCap = calculateInsuranceSum(policy.items) * PAYOUT_CAP_MULTIPLIER;
  const totalReimbursed = claimStep.incident.damages.reduce(
    (sum, damage) => sum + reimbursementForDamage(damage, policy.items),
    0,
  );
  const payout = Math.floor(totalReimbursed);
  return { payout, remainingCap: payoutCap - payout };
};
